[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-hematology-oncology",
  "answer": "72세 여성의 무통성 림프절종대 + 야간발한 + Hb 8.1 + LDH 상승은 B-증상 동반 림프증식성 질환(림프종 우선)의 전형적 조합으로, 조직학적 확정 진단 없이는 감별할 수 없습니다. 확정 진단 경로는 '림프절 절제 생검 → 조직병리 + 면역조직화학 → 유세포분석·FISH·분자검사 → 골수 생검' 순이며, 동시에 종양 응급(척수압박·상대정맥증후군·고칼슘혈증·종양용해)과 호중구감소성 발열 등 시간 민감 상태를 먼저 배제해야 합니다. 다만 조직검사·면역표현형·FISH·유세포·골수검사는 이 SP가 지시·판독하는 영역이 아니며, 실제 시행·해석은 kdoctor-pathology / kdoctor-laboratory-medicine / kdoctor-radiology 협진과 담당 혈액종양내과 전문의가 담당합니다.",
  "red_flag": {
    "present": false,
    "items": [
      {
        "id": "HO4(부분)",
        "evidence": "Hb 8.1 g/dL(환자 제공) + 72세 — 빈혈 자체는 중등도이나 심한 빈혈(숨참·어지럼·실신·가슴 두근거림) 동반 여부 미확인",
        "basis": "measurement"
      },
      {
        "id": "HO8(점검 필요)",
        "evidence": "암 환자에서 새로 생긴 등 통증 + 다리 힘 빠짐·배뇨·배변 이상은 척수압박 시사 — 현재 보고되지 않음",
        "basis": "history"
      },
      {
        "id": "HO9(점검 필요)",
        "evidence": "심한 갈증·구역·혼동·변비(고칼슘혈증), 얼굴·목 부종+숨참(상대정맥증후군) — 현재 보고되지 않음",
        "basis": "history"
      }
    ]
  },
  "hypotheses": [
    {
      "name": "림프종(비호지킨 B세포 림프종, 특히 미만성 거대 B세포 림프종 등 공격성 아형)",
      "icd10": "C83.x / C85.x",
      "must_not_miss": true,
      "probability_band": "high",
      "supports": [
        { "text": "무통성 림프절종대", "basis": "history" },
        { "text": "야간발한(B 증상)", "basis": "history" },
        { "text": "Hb 8.1(빈혈)", "basis": "measurement" },
        { "text": "LDH 상승", "basis": "measurement" },
        { "text": "72세 — 연령 자체가 위험도 상승 인자", "basis": "guideline" }
      ],
      "against": [
        { "text": "림프절 조직검사·면역표현형·유세포·FISH·골수 결과 미확인 — 확정 진단·아형 특정 불가", "basis": "guideline" },
        { "text": "발열·체중감소 등 다른 B 증상 여부 미확인", "basis": "history" }
      ]
    },
    {
      "name": "호지킨 림프종",
      "icd10": "C81.x",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "무통성 림프절종대 + 야간발한", "basis": "history" },
        { "text": "빈혈 + LDH 상승", "basis": "measurement" }
      ],
      "against": [
        { "text": "연령(72세)에서 호지킨 림프종 빈도는 상대적으로 낮음", "basis": "guideline" },
        { "text": "조직학 소견 미확인", "basis": "guideline" }
      ]
    },
    {
      "name": "만성 림프구성 백혈병 / 소림프구성 림프종",
      "icd10": "C91.1 / C83.0",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "고령 여성, 무통성 림프절종대", "basis": "guideline" },
        { "text": "빈혈 동반 가능", "basis": "guideline" }
      ],
      "against": [
        { "text": "말초혈액 림프구 수·유세포분석 미확인", "basis": "measurement" }
      ]
    },
    {
      "name": "결핵성 림프절염 또는 기타 감염성 림프절종대",
      "icd10": "A18.2 등",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "야간발한 + 림프절종대 + 빈혈(LDH 상승도 동반 가능)", "basis": "history" }
      ],
      "against": [
        { "text": "체중감소 외 다른 결핵 동반 증상(기침·발열 양상) 미확인", "basis": "history" },
        { "text": "림프절 크기·경도·부위 미확인", "basis": "history" }
      ]
    },
    {
      "name": "전이성 고형암(림프절 전이, 특히 두경부·폐·위장관 원발)",
      "icd10": "C77.x 등",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "고령, 무통성 림프절종대, 빈혈, LDH 상승", "basis": "guideline" }
      ],
      "against": [
        { "text": "원발 증상·영상 미확인", "basis": "history" }
      ]
    },
    {
      "name": "골수증식성/골수이형성 질환 및 기타 혈액 질환(예: 원발성 골수섬유증, MDS)",
      "icd10": "D45 / D46 등",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "고령 + 빈혈 + LDH 상승", "basis": "guideline" }
      ],
      "against": [
        { "text": "말초혈액 도말·골수검사 미확인", "basis": "measurement" }
      ]
    },
    {
      "name": "자가면역/약물성 림프절종대 및 용혈성 빈혈 병발",
      "icd10": "D59.x / L04 등 관련 코드 상이",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "림프절종대 + 빈혈 조합", "basis": "guideline" }
      ],
      "against": [
        { "text": "약물 이력·용혈 표지자(DAT, 망상적혈구) 미확인", "basis": "measurement" }
      ]
    }
  ],
  "missing_info": [
    "무통성 림프절종대의 부위·크기·개수·경도와 지속 기간, 그리고 발열·체중감소 등 다른 B 증상 동반 여부(+최근 감염·약물 이력)를 알려 주세요."
  ],
  "suggested_tests": [
    { "name": "림프절 절제 생검(excisional biopsy) + 조직병리·면역조직화학", "purpose": "림프종 확정 진단 및 아형 분류 — FNA/총생검보다 절제생검이 원칙", "urgency": "now", "basis": "guideline" },
    { "name": "유세포분석(flow cytometry) — 말초혈액·림프절·골수 검체", "purpose": "B/T 세포 클론성 및 면역표현형 파악", "urgency": "now", "basis": "guideline" },
    { "name": "FISH / 분자검사(예: MYC, BCL2, BCL6 재배열, 필요 시 NGS)", "purpose": "고등급 B세포 림프종(double-hit 등) 및 아형 감별", "urgency": "24h", "basis": "guideline" },
    { "name": "골수 흡인·생검", "purpose": "골수 침범 여부 — 병기 결정에 필요", "urgency": "24h", "basis": "guideline" },
    { "name": "CBC·말초혈액 도말·LDH·요산·칼슘·신기능·간기능·응고검사", "purpose": "종양용해증후군·고칼슘혈증·응고 이상 평가", "urgency": "now", "basis": "guideline" },
    { "name": "LDH·β2-microglobulin·알부민 등 예후 지표(IPI 구성 항목)", "purpose": "위험도 분류 보조(치료 결정은 담당 전문의)", "urgency": "24h", "basis": "guideline" },
    { "name": "흉·복부·골반 CT 및 PET-CT", "purpose": "병기 결정 및 림프절 분포 평가", "urgency": "24h", "basis": "guideline" },
    { "name": "심초음파(LVEF)", "purpose": "anthracycline 기반 치료 예정 시 심기능 기준선", "urgency": "routine", "basis": "guideline" },
    { "name": "B형·C형 간염, HIV, 결핵(IGRA/흉부영상)", "purpose": "감별 및 면역억제 치료 전 스크리닝", "urgency": "24h", "basis": "guideline" }
  ],

