[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-infectious-disease",
  "answer": "무통성 림프절종대 + 야간발한 + 빈혈 + LDH 상승은 감염(특히 결핵성 림프절염, EBV/CMV, HIV, 브루셀라·톡소플라즈마 등)보다 림프종 등 혈액종양 가능성이 더 높은 조합이지만, 감염내과 관점에서는 결핵(폐외 포함)과 HIV·EBV/CMV를 병행 배제하는 것이 우선이다. 검사는 (1) 결핵(I Graham: IGRA/TST, 림프절 FNA/생검 AFB 도말·배양·TB-PCR, 흉부 영상) (2) HIV 항체/항원·p24 (3) EBV/CMV 혈청(IgM/IgG, 필요시 CMV PCR) 순으로 즉시~24시간 내 시행하고, 림프절 생검(조직병리+미생물 검사 동시 의뢰)이 진단의 결정적 검사다.",
  "red_flag": {
    "present": true,
    "items": [
      { "id": "unexplained_lymphadenopathy_B_sx", "evidence": "무통성 림프절종대 + 야간발한 + 빈혈 + LDH 상승 (B증상 조합)", "basis": "history" },
      { "id": "aged_65_over", "evidence": "72세 여성", "basis": "history" }
    ]
  },
  "hypotheses": [
    {
      "name": "결핵성 림프절염(폐외 결핵)",
      "icd10": "A18.2",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "무통성 경부 림프절종대는 결핵성 림프절염의 전형적 양상", "basis": "guideline" },
        { "text": "야간발한·빈혈·LDH 상승은 만성 감염에서도 관찰될 수 있음", "basis": "guideline" }
      ],
      "against": [
        { "text": "기침·객담·체중감소 등 호흡기 증상·전신 소모 증상 유무 미확인", "basis": "history" },
        { "text": "흉부 영상·IGRA/TST 결과 미확인", "basis": "history" }
      ]
    },
    {
      "name": "HIV 감염(급성 또는 진행성)",
      "icd10": "B24",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "원인 불명 림프절종대 + 전신 증상 조합에서 HIV 선별 필요", "basis": "guideline" }
      ],
      "against": [
        { "text": "성접촉·주사기구 공유·수혈 이력 미확인", "basis": "history" }
      ]
    },
    {
      "name": "EBV/CMV 감염(또는 재활성)",
      "icd10": "B27.9 / B25.9",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "림프절종대 + 발열/야간발한 + 간효소 이상·LDH 상승 양상이 EBV/CMV에서 관찰됨", "basis": "guideline" }
      ],
      "against": [
        { "text": "72세에서 원발 EBV 감염은 드묾; 면역억제 여부·이식·항암력 미확인", "basis": "history" }
      ]
    },
    {
      "name": "림프종(호지킨/비호지킨) — 혈액종양 협진 필요",
      "icd10": "C81~C85",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "무통성 림프절종대 + B증상(야간발한) + 빈혈 + LDH 상승은 림프종의 고전적 조합", "basis": "guideline" },
        { "text": "고령(72세)", "basis": "history" }
      ],
      "against": [
        { "text": "림프절 크기·분포·고정 여부, 비장·간 비대, 말초혈액 도말·CBC 미확인", "basis": "history" }
      ]
    },
    {
      "name": "브루셀라증·톡소플라즈마증 등 기타 만성 감염",
      "icd10": "A23 / B58",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "만성 림프절종대 + 전신 증상에서 동물·음식 노출 관련 감염 감별 필요", "basis": "guideline" }
      ],
      "against": [
        { "text": "가축 접촉·미살균 유제품·날음식 섭취 이력 미확인", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "림프절의 위치·크기·개수·고정 여부와 비장/간 비대 여부, 그리고 성접촉·주사기구·동물/여행 노출력 중 하나(가장 판별력이 큰 항목)"
  ],
  "suggested_tests": [
    { "name": "림프절 FNA 또는 절제 생검 — 조직병리 + AFB 도말·배양·TB-PCR + 세균/진균 배양 + 유세포분석", "purpose": "결핵성 림프절염 및 림프종 동시 감별(결정적 검사)", "urgency": "24h", "basis": "guideline" },
    { "name": "IGRA(QuantiFERON 등) 또는 TST, 흉부 X선(필요시 CT)", "purpose": "결핵 선별", "urgency": "24h", "basis": "guideline" },
    { "name": "HIV 항체/항원(p24 포함) 선별검사", "purpose": "HIV 감염 배제", "urgency": "24h", "basis": "guideline" },
    { "name": "EBV VCA IgM/IgG·EA, EBNA IgG; CMV IgM/IgG(필요 시 CMV DNA PCR)", "purpose": "EBV/CMV 감염 또는 재활성 확인", "urgency": "24h", "basis": "guideline" },
    { "name": "CBC·말초혈액 도말, LDH, 요산, β2-microglobulin, 간/신기능, 단백 전기영동, CRP/ESR", "purpose": "전신 상태·혈액종양 시사 소견 파악", "urgency": "24h", "basis": "guideline" },
    { "name": "브루셀라·톡소플라즈마 혈청(노출력 있을 때), RPR/TPHA", "purpose": "기타 만성 감염 감별", "urgency": "routine", "basis": "guideline" },
    { "name": "혈액종양 협진 및 골수검사·PET-CT 의뢰", "purpose": "림프종 확정 진단·병기", "urgency": "24h", "basis": "consult" }
  ],
  "suggested_treatments": [
    { "kind": "referral", "description": "림프절 생검과 혈액종양 협진을 우선 진행. 결핵 확정 진단 전 항결핵제 경험적 투여는 조직검사 결과 확인 후 결정.", "basis": "guideline" },
    { "kind": "self_care", "description": "야간발한·발열 시 수분 섭취, 체온·증상 일지 기록. 기침 예절·마스크 등 호흡기 전파 예방 수칙(결핵 가능성 배제 전까지).", "basis": "guideline" }
  ],
  "handoff": {
    "better_specialty": "kdoctor-hematology-oncology",
    "reason": "무통성 림프절종대 + B증상 + 빈혈 + LDH 상승은 혈액종양(림프종) 가능성이 높고 조직 생검·골수검사·PET-CT 등 혈액종양 주도 평가가 필요. 결핵·HIV·EBV/CMV 등 감염 원인은 병행 배제."
  },
  "confidence": { "clinical": 3, "information": 2 },
  "warnings": [
    "림프절 위치·크기·고정 여부, 노출력(여행·동물·성접촉·주사), 흉부 증상, 면역억제 여부 미확인. missing_info 하나만 우선 확인 권장.",
    "결핵 신고 대상 여부 및 접촉자 관리 필요 여부는 확정 진단 시 관할 보건소(질병관리청 1339) 문의."
  ]
